arguments.command:
curl -sS -H 'Authorization: Bearer <TOKEN>' 'https://slack.com/api/conversations.list?exclude_archived=true&types=public_channel,private_channel&limit=1000' > /tmp/launch-channels.json
curl -sS -H 'Authorization: Bearer <TOKEN>' 'https://slack.com/api/users.list?limit=1000' > /tmp/launch-users.json
python - <<'PY'
import json
for f,k in [('/tmp/launch-channels.json','channels'),('/tmp/launch-users.json','members')]:
 d=json.load(open(f)); print(f, 'ok', d.get('ok'),'error',d.get('error'),'metadata',d.get('response_metadata'))
 for x in d.get(k,[]):
  if k=='channels' and ('launch' in x.get('name','').lower() or x.get('topic',{}).get('value')=='Go-live checklist and cutover plan'): print(json.dumps(x))
  if k=='members' and 'omar' in json.dumps(x).lower(): print(json.dumps(x))
PY

